fn is_palindrome(text: Vec<char>) -> bool {
    let mut i = 0;
    let mut j = text.len().saturating_sub(1); // Handle empty case
    
    while i < j {
        let left_char = text[i].to_ascii_lowercase();
        let right_char = text[j].to_ascii_lowercase();
        
        if left_char != right_char {
            return false;
        }
        
        i += 1;
        j -= 1;
    }
    
    true
}